with feeders as (
    select
        md5(upper('HUB_PROPOSAL|' || (HUB_PROPOSAL_BK__QUOTE_REF_NO))) as HUB_PROPOSAL_HK
        , PREV_DISEASE_COVERED_DESC as RESPONSE_VALUE
        , 'BJAZ_HG_POL_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hg_pol_dtls') }}
    where (nullif(trim(QUOTE_REF_NO),'')) is not null
),

resolved as (
    select
        HUB_PROPOSAL_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then RESPONSE_VALUE end) as RESPONSE_VALUE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PROPOSAL_HK
),

hashed as (
    select
        *,
        case when RESPONSE_VALUE is not null
                     then md5(upper(coalesce(cast(RESPONSE_VALUE as varchar), '')))
                end as SAT_PROPOSAL_QUESTIONNAIRE_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PROPOSAL_HK is not null
  and SAT_PROPOSAL_QUESTIONNAIRE_HASHDIFF is not null
